<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Model Capabilities Benchmark</title>
  <script src="/app/libs/chart.js"></script>
  <style>
    :root {
      --bg: #f8f9fa;
      --surface: #ffffff;
      --border: #dee2e6;
      --text: #212529;
      --text-dim: #6c757d;
      --font-body: 'IBM Plex Sans', -apple-system, sans-serif;
      --font-mono: 'IBM Plex Mono', monospace;
    }

    body {
      background-color: var(--bg);
      color: var(--text);
      font-family: var(--font-body);
      margin: 0;
      padding: 40px;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      box-sizing: border-box;
    }

    .ve-card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 32px;
      width: 1200px;
      box-shadow: 0 4px 24px rgba(0,0,0,0.04);
    }

    .header {
      margin-bottom: 24px;
    }

    .title {
      font-size: 24px;
      font-weight: 600;
      margin: 0 0 8px 0;
      letter-spacing: -0.01em;
    }

    .subtitle {
      color: var(--text-dim);
      font-size: 14px;
      margin: 0;
    }

    .chart-container {
      position: relative;
      height: 600px;
      width: 100%;
    }
  </style>
</head>
<body>
  <div class="ve-card">
    <div class="header">
      <h1 class="title">AI Model Capability Profiles & Trade-offs</h1>
      <p class="subtitle">Parallel coordinates analysis across 8 benchmark dimensions (0-100 normalized scale)</p>
    </div>
    <div class="chart-container">
      <canvas id="benchmarkChart"></canvas>
    </div>
  </div>

  <script>
    const ctx = document.getElementById('benchmarkChart').getContext('2d');

    const dimensions = [
      "Reasoning",
      "Inference Speed",
      "Math / Quantitative",
      "Multimodal Understanding",
      "Code Generation",
      "Language Understanding",
      "Instruction Following",
      "Knowledge Recall"
    ];

    const data = [
      { model: "GPT-4o", family: "GPT", type: "flagship", Reasoning: 92, "Code Generation": 89, "Math / Quantitative": 85, "Language Understanding": 91, "Multimodal Understanding": 88, "Instruction Following": 90, "Inference Speed": 42, "Knowledge Recall": 93 },
      { model: "GPT-4o-mini", family: "GPT", type: "light", Reasoning: 74, "Code Generation": 76, "Math / Quantitative": 68, "Language Understanding": 80, "Multimodal Understanding": 72, "Instruction Following": 82, "Inference Speed": 78, "Knowledge Recall": 79 },
      { model: "Claude 3.5 Sonnet", family: "Claude", type: "flagship", Reasoning: 94, "Code Generation": 93, "Math / Quantitative": 82, "Language Understanding": 93, "Multimodal Understanding": 85, "Instruction Following": 95, "Inference Speed": 38, "Knowledge Recall": 90 },
      { model: "Claude 3 Haiku", family: "Claude", type: "light", Reasoning: 68, "Code Generation": 70, "Math / Quantitative": 60, "Language Understanding": 76, "Multimodal Understanding": 65, "Instruction Following": 78, "Inference Speed": 91, "Knowledge Recall": 72 },
      { model: "Gemini 1.5 Pro", family: "Gemini", type: "flagship", Reasoning: 88, "Code Generation": 82, "Math / Quantitative": 72, "Language Understanding": 87, "Multimodal Understanding": 95, "Instruction Following": 86, "Inference Speed": 45, "Knowledge Recall": 91 },
      { model: "Gemini 1.5 Flash", family: "Gemini", type: "light", Reasoning: 70, "Code Generation": 68, "Math / Quantitative": 58, "Language Understanding": 75, "Multimodal Understanding": 82, "Instruction Following": 74, "Inference Speed": 88, "Knowledge Recall": 74 },
      { model: "LLaMA 3.1 405B", family: "LLaMA", type: "flagship", Reasoning: 86, "Code Generation": 84, "Math / Quantitative": 90, "Language Understanding": 84, "Multimodal Understanding": 45, "Instruction Following": 80, "Inference Speed": 35, "Knowledge Recall": 88 },
      { model: "LLaMA 3.1 70B", family: "LLaMA", type: "light", Reasoning: 76, "Code Generation": 74, "Math / Quantitative": 78, "Language Understanding": 75, "Multimodal Understanding": 40, "Instruction Following": 72, "Inference Speed": 62, "Knowledge Recall": 76 },
      { model: "Qwen2.5 72B", family: "Qwen", type: "flagship", Reasoning: 83, "Code Generation": 86, "Math / Quantitative": 92, "Language Understanding": 82, "Multimodal Understanding": 52, "Instruction Following": 81, "Inference Speed": 48, "Knowledge Recall": 85 },
      { model: "Qwen2.5 7B", family: "Qwen", type: "light", Reasoning: 58, "Code Generation": 62, "Math / Quantitative": 70, "Language Understanding": 64, "Multimodal Understanding": 38, "Instruction Following": 60, "Inference Speed": 93, "Knowledge Recall": 60 }
    ];

    const familyColors = {
      "GPT": "#0284c7",      // Blue
      "Claude": "#6b21a8",   // Purple
      "Gemini": "#059669",   // Green
      "LLaMA": "#d97706",    // Orange
      "Qwen": "#be123c"      // Red
    };

    const datasets = data.map(d => {
      const isFlagship = d.type === "flagship";
      return {
        label: d.model,
        data: dimensions.map(dim => d[dim]),
        borderColor: familyColors[d.family],
        backgroundColor: familyColors[d.family],
        borderWidth: isFlagship ? 4 : 2,
        borderDash: isFlagship ? [] : [5, 5],
        pointRadius: isFlagship ? 5 : 3,
        pointBackgroundColor: '#fff',
        pointBorderWidth: 2,
        tension: 0.1 // Slight curve for aesthetics, but keeps parallel coord look
      };
    });

    new Chart(ctx, {
      type: 'line',
      data: {
        labels: dimensions,
        datasets: datasets
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: {
            position: 'right',
            labels: {
              usePointStyle: true,
              padding: 20,
              font: {
                family: "'IBM Plex Sans', -apple-system, sans-serif",
                size: 13
              }
            }
          },
          tooltip: {
            backgroundColor: 'rgba(255, 255, 255, 0.95)',
            titleColor: '#212529',
            bodyColor: '#495057',
            borderColor: '#dee2e6',
            borderWidth: 1,
            padding: 12,
            boxPadding: 6,
            usePointStyle: true,
            titleFont: { size: 14, weight: 'bold' }
          }
        },
        scales: {
          y: {
            min: 0,
            max: 100,
            grid: {
              color: '#f1f3f5',
              drawBorder: false
            },
            ticks: {
              font: { family: "'IBM Plex Mono', monospace", size: 12 },
              color: '#868e96',
              stepSize: 20
            },
            title: {
              display: true,
              text: 'Normalized Score (0-100)',
              font: { family: "'IBM Plex Sans', sans-serif", size: 12 },
              color: '#868e96'
            }
          },
          x: {
            grid: {
              color: '#dee2e6', // Emphasize vertical axes for parallel coords
              lineWidth: 1,
              drawBorder: true
            },
            ticks: {
              font: { family: "'IBM Plex Sans', sans-serif", size: 13, weight: '500' },
              color: '#495057',
              maxRotation: 45,
              minRotation: 45
            }
          }
        }
      }
    });
  </script>
</body>
</html>
EOF

